/**
 * Text-first renderers.
 * Markdown/HTML preview runs in-browser. Office/PDF binaries are generated by
 * the local CLI adapter; GitHub Pages never pretends to generate DOCX/PDF.
 */
const esc = s => String(s ?? "").replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const plain = value => {
  if (value === null || value === undefined) return "[UNSPECIFIED]";
  if (typeof value === "string") return value;
  return "```json\n" + JSON.stringify(value, null, 2) + "\n```";
};

export function renderMarkdown(document, template) {
  const sections = template.sections || template.slides || [];
  const lines = [`# ${document.title}`, "", `Document ID: ${document.document_id}`,
    `Template: ${document.template_id}@${document.template_version}`,
    `Project: ${document.project_id}`, `Status: ${document.status}`, ""];
  for (const section of sections) {
    const instance = document.sections?.[section.id];
    lines.push(`## ${section.title}`, "");
    if (!instance) { lines.push("> [SECTION NOT POPULATED]", ""); continue; }
    const fields = Object.entries(instance.content || {});
    if (!fields.length && instance.body) lines.push(plain(instance.body), "");
    for (const [fieldId, cell] of fields) {
      lines.push(`### ${fieldId.replace(/[_-]/g," ")}`, "", plain(cell.value), "");
      if (cell.value_state && cell.value_state !== "PROVIDED") {
        lines.push(`*Data state: ${cell.value_state}; source: ${cell.source?.kind || "UNSPECIFIED"}*`, "");
      }
    }
  }
  if (document.references?.length) {
    lines.push("## References", "");
    for (const ref of document.references) lines.push(`- ${esc(ref.authors || "Author unspecified")}. ${esc(ref.title)}. ${esc(ref.venue || "")}. ${esc(ref.doi || ref.url || "")}`, "");
  }
  lines.push("## Generation provenance", "", "```json", JSON.stringify({
    source_baseline: document.source_baseline,
    template_id: document.template_id,
    template_version: document.template_version,
    generation: document.generation
  }, null, 2), "```");
  return lines.join("\n");
}

export function renderHTML(document, template) {
  const md = renderMarkdown(document, template);
  // Conservative Markdown subset renderer. No raw HTML is interpreted.
  const html = md.split("\n").map(line => {
    if (line.startsWith("# ")) return `<h1>${esc(line.slice(2))}</h1>`;
    if (line.startsWith("## ")) return `<h2>${esc(line.slice(3))}</h2>`;
    if (line.startsWith("### ")) return `<h3>${esc(line.slice(4))}</h3>`;
    if (line.startsWith("> ")) return `<blockquote>${esc(line.slice(2))}</blockquote>`;
    if (line.startsWith("- ")) return `<p>• ${esc(line.slice(2))}</p>`;
    if (!line.trim()) return "";
    if (line.startsWith("```")) return "";
    return `<p>${esc(line)}</p>`;
  }).join("\n");
  return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${esc(document.title)}</title><style>body{font:16px/1.55 system-ui,sans-serif;max-width:900px;margin:3rem auto;padding:0 1.2rem;color:#18212b}h1,h2,h3{line-height:1.2}h2{margin-top:2.5rem;border-bottom:1px solid #ddd;padding-bottom:.4rem}blockquote{border-left:3px solid #999;padding-left:1rem;color:#555}</style><main>${html}</main></html>`;
}
